#include "../src/scene_live_materials.hpp"

#include <iostream>

using namespace t3render::live;

// Text fixture input is generated by the Python test; it is not a scene or a
// runtime capture format. Each process handles one bounded BSP section.
int main() {
    Snapshot snapshot;snapshot.map="SouthQuarter1_int1";snapshot.map_sha256=std::string(64,'a');
    snapshot.conventions.length_unit=LengthUnit::T3Unit;snapshot.conventions.axes=Axes::T3Xyz;
    snapshot.conventions.up_axis=UpAxis::Z;snapshot.conventions.meters_per_unit=0.01905f;
    auto bed=std::make_shared<Resource>();bed->name="INNbed1A1";bed->source_sha256=std::string(64,'b');
    bed->id="mesh:"+snapshot.map+":"+snapshot.map_sha256+":"+bed->source_sha256+":innbed1a1";
    ResidentMesh instance;instance.resource=bed;instance.selection.resource_id=bed->id;
    instance.selection.instance_id="actor:"+snapshot.map+":"+snapshot.map_sha256+":StaticMeshActor__1520";
    instance.selection.generation=1;instance.selection.binding=BindingEvidence::Candidate;instance.selection.sections={0};
    for (auto& value:instance.selection.transform) if (!(std::cin>>value)) return 2;
    snapshot.meshes.push_back(std::move(instance));
    std::uint32_t vertices=0,indices=0,first=0,count=0;std::string material;
    if (!(std::cin>>vertices>>indices>>first>>count>>material) || !vertices || vertices>1000000 ||
        !indices || indices>3000000) return 2;
    Resource bsp;bsp.kind=ResourceKind::BspBlock;bsp.geometry.positions.resize(vertices);
    for (auto& point:bsp.geometry.positions) for (auto& value:point) if (!(std::cin>>value)) return 2;
    bsp.geometry.indices.resize(indices);
    for (auto& index:bsp.geometry.indices) if (!(std::cin>>index)) return 2;
    bsp.geometry.sections.push_back({"section",first,count,std::nullopt});
    BedroomAnchor anchor;std::vector<BedroomMaterialRun> runs;
    if (!FindBedroomAnchor(snapshot,anchor) || !PartitionBedroomMaterial(anchor,bsp,0,material,runs)) return 1;
    for (const auto& run:runs)
        std::cout<<run.first_index<<' '<<run.index_count<<' '<<(run.replacement ? *run.replacement : "-")<<'\n';
}
